#!/usr/bin/env bash
#
# nexum-burn-scanner-fix.sh
# =============================================================================
# FIX the burn-scanner that wasn't recovering stuck bridges. ROOT CAUSE: the DB
# row stores the amount as HUMAN USDC (e.g. 1.5) but the on-chain DepositForBurn
# event emits BASE UNITS (1500000). The scanner compared them directly, so the
# amount check never matched and nothing was ever recovered - the row sat at
# "In progress" forever.
#
# THIS: replaces services/bridge/burnScanner.ts only. Converts the row amount to
# base units (exact string method, matching the frontend's toUnits) before
# comparing, and adds diagnostic logging so any remaining non-match is
# explainable from the API logs (logs found, amount/domain/recipient compared).
#
# Depends on the burn-scanner already being applied (repository.ts +
# reconciler.ts from nexum-bridge-burn-scanner.sh). This only swaps the scanner.
#
# DELIVERY: base64 heredoc; decode + sha256 verify; backup; idempotent; --revert.
# VERIFY AFTER: cd nexum-api && npx tsc --noEmit
# =============================================================================
set -euo pipefail
find_root() { local d="$PWD"; while [ "$d" != "/" ]; do [ -d "$d/nexum-api/src/services/bridge" ] && { echo "$d"; return; }; d="$(dirname "$d")"; done; [ -d "$HOME/AfriFX/Nexum-main/nexum-api/src/services/bridge" ] && { echo "$HOME/AfriFX/Nexum-main"; return; }; [ -d "$HOME/AfriFX/nexum-api/src/services/bridge" ] && { echo "$HOME/AfriFX"; return; }; return 1; }
ROOT="$(find_root)" || { echo "ERROR: repo root not found."; exit 1; }
echo "Repo root: $ROOT"
STAMP="$(date +%Y%m%d-%H%M%S)"
BACKUP_DIR="$ROOT/.nexum-burn-scanner-fix-backups"
SC_PATH="$ROOT/nexum-api/src/services/bridge/burnScanner.ts"
SC_SHA="9e1a4c650788cc43bc996b4a7e0413117fdbf10e76af86ed2a0ec485059c5d53"; SC_B64=""
if [ "${1:-}" = "--revert" ]; then
  p="$(ls -1tr "$BACKUP_DIR"/burnScanner.ts.* 2>/dev/null | head -n1 || true)"
  [ -n "${p:-}" ] && [ -f "$p" ] && cp -f "$p" "$SC_PATH" && echo "restored burnScanner.ts" || echo "no backup"
  rm -f "$BACKUP_DIR"/burnScanner.ts.*; rmdir "$BACKUP_DIR" 2>/dev/null || true; echo "revert complete."; exit 0
fi
if [ ! -f "$SC_PATH" ]; then echo "ERROR: burnScanner.ts not found. Apply nexum-bridge-burn-scanner.sh first."; exit 1; fi
mkdir -p "$BACKUP_DIR"
tmp="$(mktemp)"; printf '%s' "$SC_B64" | base64 -d > "$tmp" || { echo "decode fail"; rm -f "$tmp"; exit 1; }
got="$(sha256sum "$tmp" | cut -d' ' -f1)"
[ "$got" = "$SC_SHA" ] || { echo "ERROR checksum"; echo " expected $SC_SHA"; echo " got      $got"; rm -f "$tmp"; exit 1; }
echo "  verified burnScanner.ts"
cp -f "$SC_PATH" "$BACKUP_DIR/burnScanner.ts.$STAMP" && echo "  backed up existing"
mv -f "$tmp" "$SC_PATH"; echo "  wrote $SC_PATH"
echo; echo "== DONE == Verify: cd $ROOT/nexum-api && npx tsc --noEmit ; Revert: bash $(basename "$0") --revert"
